// #1 //
void insernam(char fist[20], char last[20])
{
printf ("                         First Name: ");
scanf("%s",fist);
printf ("                         Last  Name: ");
scanf("%s",last);
}
// #2 //
void gendir(int gend, char call1[20], char call2[20], char call3[20], char call4[20], int* gendm, int* gendf)
{
	switch(gend){
		case 1:{
			strcpy(call1, "Male");
			strcpy(call2, "guy");
			strcpy(call3, "boy");
			strcpy(call4, "man");
			*gendm = 1;
			*gendf = 0;
			break;
		}
		case 2:{
			strcpy(call1, "Female");
			strcpy(call2, "girl");
			strcpy(call3, "girl");
			strcpy(call4, "woman");
			*gendm = 0;
			*gendf = 1;
			break;
		}
	}
}
// #3 //
void claz(int claz, char claz1[20], char claz1a[20], int* claz1c, int* claz2, int* claz3)
{
	switch(claz){
		case 1:{
			strcpy(claz1, "Warrior");
			strcpy(claz1a, "warrior");
			*claz1c= 1;
			*claz2= 0;
			*claz3= 0;
			break;
		}
		case 2:{
			strcpy(claz1, "Mage");
			strcpy(claz1a, "mage");
			*claz1c= 0;
			*claz2= 1;
			*claz3= 0;
			break;
		}
		case 3:{
			strcpy(claz1, "Rogue");
			strcpy(claz1a, "rogue");
			*claz1c= 0;
			*claz2= 0;
			*claz3= 1;
			break;
		}
	}
}

